  // earlyDetection / pushDescription are MAIN-only by design (FIFO is for
  // main-spawn descriptions; nested spawn description comes from meta.json).
  // For non-MAIN with isTaskToolUse, recordSpawn handles the parent linkage.
  const detector = createMockDetector();
  const parsed = createMockParsedLine({
    isTaskToolUse: true,
    taskDescription: 'should not push',
    // No toolUseResult here — we're only testing the Task tool_use path.
    raw: {},
  });

  const mockParser: LineParser = {
    parse: (() => {
      let called = false;
      return () => {
        if (!called) {
          called = true;
          return parsed;
        }
        return null;
      };
    })(),
  };

  const config: OnLineHandlerConfig = {
    parsers: new Map([['[abc1234]', mockParser]]),
    formatter: createMockFormatter(),
    detector,
    onOutput: () => {},
    verbose: false,
  };

  const handler = createOnLineHandler(config);
