      return () => {
        if (!called) {
          called = true;
          return parsed;
        }
        return null;
      };
    })(),
  };

  const config: OnLineHandlerConfig = {
    parsers: new Map([['[abc1234]', mockParser]]),
    formatter: createMockFormatter(),
    detector,
    onOutput: () => {},
    verbose: false,
  };

  const handler = createOnLineHandler(config);
